import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class PrivateTest {
@org.junit.jupiter.api.io.TempDir java.nio.file.Path dir;int sequence;
java.nio.file.Path input(String s)throws Exception{var p=dir.resolve("вход-"+(sequence++)+".txt");java.nio.file.Files.writeString(p,s,java.nio.charset.StandardCharsets.UTF_8);return p;}
java.nio.file.Path output(){return dir.resolve("выход-"+(sequence++)).resolve("результат.txt");}
java.util.List<String> lines(java.nio.file.Path p)throws Exception{return java.nio.file.Files.readAllLines(p,java.nio.charset.StandardCharsets.UTF_8);}
@Test void singletonMissingAndSameFileProtection()throws Exception{var in=input("-2147483648\n");var out=output();TaskBinding.run(in,out);assertTrue(java.util.Arrays.deepEquals(new int[][]{{Integer.MIN_VALUE}},TaskBinding.read(out).transposed()));var old=dir.resolve("old.txt");java.nio.file.Files.writeString(old,"KEEP");assertThrows(Exception.class,()->TaskBinding.run(dir.resolve("missing"),old));assertEquals("KEEP",java.nio.file.Files.readString(old));var fresh=output();assertThrows(Exception.class,()->TaskBinding.run(dir.resolve("also-missing"),fresh));assertFalse(java.nio.file.Files.exists(fresh));byte[] bytes=java.nio.file.Files.readAllBytes(in);assertThrows(Exception.class,()->TaskBinding.run(in,in));assertArrayEquals(bytes,java.nio.file.Files.readAllBytes(in));java.nio.file.Files.createDirectory(dir.resolve("padding"));var normalized=dir.resolve("padding/../"+in.getFileName());assertThrows(Exception.class,()->TaskBinding.run(in,normalized));assertArrayEquals(bytes,java.nio.file.Files.readAllBytes(in));}
@Test void supportedLinksProtectInput()throws Exception{var in=input("7\n");for(boolean symbolic:new boolean[]{false,true}){var alias=dir.resolve(symbolic?"sym":"hard");try{if(symbolic)java.nio.file.Files.createSymbolicLink(alias,in);else java.nio.file.Files.createLink(alias,in);}catch(java.io.IOException|UnsupportedOperationException e){System.out.println("link-unavailable="+symbolic+":"+e);continue;}assertThrows(Exception.class,()->TaskBinding.run(in,alias));assertEquals("7\n",java.nio.file.Files.readString(in));}}
}
